($q$Charles Darwin University$q$, $q$Vice-Chancellor's International High Achievers Scholarship (VCIHAS)$q$, $q$Partial$q$, $q$Undergraduate$q$, $q$NOT YET CHECKED against the official page: this came from a web search and the figures may be wrong or out of date. Confirm on the official page before you rely on it. Requirements and Ghana eligibility: New international student commencing in Semester 1 or 2 of 2027, with at least 95% overall in the highest completed qualification. Must meet course and English requirements and cannot hold another Austral Direct entry with WASSCE: WASSCE accepted for undergraduate entry Note: the source text for this award was cut off, so some details may be missing.$q$, $q$50% tuition reduction for the minimum duration of the degree.$q$, null::text)
) as v(school, name, ftype, lvl, criteria, award, url);

update public.scholarships c set funding_type = n.ftype, level = n.lvl, criteria = n.criteria, award_note = n.award,
  link = coalesce(n.url, c.link), source_url = coalesce(n.url, c.source_url)
from _new_sch n join public.schools s on s.name = n.school
where c.school_id = s.id and c.name = n.name and c.verified = false;

insert into public.scholarships (name, funder, country, funding_type, level, criteria, award_note, link, source_url, school_id, verified, demo)
select n.name, s.name, s.country, n.ftype, n.lvl, n.criteria, n.award, n.url, n.url, s.id, false, false
from _new_sch n join public.schools s on s.name = n.school
where not exists (select 1 from public.scholarships x where x.school_id = s.id and x.name = n.name);

drop table if exists pg_temp._new_sch;

-- Check: awards per school, fully funded first.
select s.name school, count(*) awards, count(*) filter (where c.funding_type = 'Full') full_awards
from public.scholarships c join public.schools s on s.id = c.school_id group by 1 order by 3 desc, 2 desc, 1;
